<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { request } from './api'
import { orderTime } from '../../shared/orders'
import type { ImageIndexStatus,ImageSearchLog } from '../../shared/image-search'
const status=ref<ImageIndexStatus|null>(null),logs=ref<ImageSearchLog[]>([]),busy=ref(false),error=ref('')
async function load(){[status.value,logs.value]=await Promise.all([request<ImageIndexStatus>('/admin/image-search/status'),request<ImageSearchLog[]>('/admin/image-search/logs')])}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await action()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
function rebuild(){return run(async()=>{status.value=await request<ImageIndexStatus>('/admin/image-search/index','POST');await load()})}
onMounted(()=>run(load))
</script>
<template><section class="search-desk"><div class="row"><h2>以图搜图管理</h2><div><button :disabled="busy" @click="run(load)">刷新状态</button><button :disabled="busy" @click="rebuild">{{ busy?'正在处理…':'建立或更新索引' }}</button></div></div><p v-if="error" class="error" role="alert">{{ error }}</p><article v-if="status"><h3>{{ status.message }}</h3><p>当前可售图片 {{ status.eligible_images }} 张；索引 {{ status.indexed_images }} 张 / {{ status.indexed_skus }} 个规格。</p><p>{{ status.needs_rebuild?'商品状态或图片已变化，请更新索引；旧结果仍会按当前可售状态过滤。':'索引与当前可售图库一致。' }}</p><p>模型权重：{{ status.weights_ready?'已准备':'未准备' }} · 图搜依赖：{{ status.dependencies_ready?'可用':'未安装' }}</p><p v-if="status.index_version">索引版本：{{ status.index_version }}<br/>建立时间：{{ orderTime(status.created_at || '') }}</p><p>主方法：{{ status.deep_version || 'ResNet18 视觉嵌入' }}；基线：{{ status.color_version || 'HSV 颜色直方图' }}。</p><p>查询参考图不落盘；日志只保存方法、版本、耗时和结果编号，不保存原图或特征。</p></article><article><h3>最近 20 次查询</h3><p v-if="!logs.length">暂无查询记录。</p><div class="table-wrap"><table v-if="logs.length"><thead><tr><th>查询时间</th><th>方法</th><th>耗时</th><th>结果数</th><th>查询编号</th></tr></thead><tbody><tr v-for="row in logs" :key="row.query_id"><td>{{ orderTime(row.created_at) }}</td><td>{{ row.method==='deep'?'视觉嵌入':'颜色基线' }}</td><td>{{ row.elapsed_ms.toFixed(1) }} ms</td><td>{{ row.result_count }}</td><td>{{ row.query_id }}</td></tr></tbody></table></div></article></section></template>
<style scoped>.row{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}.search-desk button{width:auto;padding:10px 18px;margin:5px}.search-desk article{padding:24px;background:white;border-radius:14px;margin:20px 0;overflow-wrap:anywhere}.search-desk p{color:#62766c;line-height:1.8}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px;text-align:left}td,th{padding:12px;border-bottom:1px solid #e3e8dd;white-space:nowrap}.error{color:#a04436!important}</style>
